143:INT	filenum,             // INPUT : file number
144:INT	permissions				// INPUT : file access permissions
145:)
146:{
147:   char        *routine = "GLB_FindFile";
148:   char        filename[ _MAX_PATH ];
149:   int         handle;
150:   FILEDESC    *fd;
151:/*
152:* Scott, the ASSERT function is a macro that will be compiled-out when
153:* not debugging ( DEBUG not defined ), otherwise it calls EXIT_Assert
154:* if the expression is false ( which bails out of your program and displays
155:* the expression, file & line number of the assertion ).  This is a standard
156:* way of checking variables for correct boundries during development, and
157:* makes it easy to remove extra logic for doing so by recompiling without
158:* DEBUG defined.
159:*/
160:   ASSERT( filenum >= 0 && filenum < MAX_GLB_FILES );
161:/*
162:* create a file name and attempt to open it local first, then if it
163:* fails use the exe path and try again.
164:*/
165:   sprintf( filename, "%s%04u.glb", prefix, filenum );
166:   if ( ( handle = open( filename, permissions ) ) == -1 )
167:	{
168:      sprintf( filename, "%s%s%04u.glb", exePath, prefix, filenum );
169:   	if ( ( handle = open( filename, permissions ) ) == -1 )
170:		{
171:			if ( return_on_failure )
172:				return -1;
173:
174:         sprintf( filename, "%s%04u.glb", prefix, filenum );
175:   	   EXIT_Error ("GLB_FindFile: %s, Error #%d,%s",
176:								filename, errno, strerror( errno ) );
177:		}
178:	}
179:/*
180:* Keep file handle
181:*/
182:   fd = &filedesc[ filenum ];
183:
184:   strcpy( fd->filepath, filename );
185:   fd->permissions = permissions;
186:   fd->handle = handle;
187:
188:	return handle;
189:}
