  get(nameOrNum) {
    const it = typeof nameOrNum === 'number'
      ? this.items[nameOrNum]
      : this.items.find((x) => x.name === nameOrNum);
    return it ? this.fetch(it) : null;
  }
  indexOf(name) {
    return this.items.findIndex((x) => x.name === name);
  }
}

