cd D:/dev/ab-tasks/raptor-qwen && cat > tools/probe4.js <<'EOF'
const { GLB } = require('./glbparse.js');
const fs = require('fs');
const glb = new GLB(fs.readFileSync('data/FILE0000.GLB'));
// FX labels from FILE0000.INC
const fx = {THEME:0x63,EXPLO:0x68,EXPLO2:0x6d,BONUS:0x72,CRASH:0x77,DOOR:0x7c,FLYBY:0x81,EGRAB:0x86,GEXPLO:0x8b,GUN:0x90,JETSND:0x95,LASER:0x9a,MISSLE:0x9f,SWEP:0xa4,TURRET:0xa9,WARN:0xae,BOSS:0xb3,HIT:0xb8,ESHOT:0xbd,MON1:0xc2,MON2:0xc7,MON3:0xcc,MON4:0xd1,MON5:0xd6,MON6:0xdb,DAVE:0xe0};
for (const [name,label] of Object.entries(fx)) {
  for (let k=0;k<5;k++){
    const n = label+k;
    const it = glb.items[n];
    if(!it||it.size<8){continue;}
    const buf = glb.get(n);
    const dv=new DataView(buf.buffer,buf.byteOffset,buf.byteLength);
    const f0=dv.getUint16(0,true), rate=dv.getUint16(2,true), dsz=dv.getUint32(4,true);
    const ok = dsz + 8 === it.size;
    console.log(`${name}[${k}] n=${n} size=${it.size} f0=${f0} rate=${rate} dsz=${dsz} hdr8ok=${ok}`);
  }
  console.log('---');
}
EOF
