   WIN_SetLoadLevel ( 40 );
   ANIMS_CachePics();
   WIN_SetLoadLevel ( 60 );
   ENEMY_LoadSprites();
   WIN_SetLoadLevel ( 80 );
   TILE_CacheLevel();
   WIN_SetLoadLevel ( 100 );
   WIN_EndLoad();
}

