// Asset extractor: pulls real game data out of FILE0000.GLB / FILE0001.GLB and
// writes a single flat binary (assets/raptor.bin) plus a JSON index
// (assets/index.json) consumed by js/raptor.js.
//
// Layout of the binary: items concatenated in GLB order. Every entry is raw
// (decrypted) item bytes in its original format:
//   kind "gfx"  : GFX_PIC sprite/dense pic (see index for w/h)
//   kind "sfx"  : Apogee 8-bit PCM: {type u16, rate u16, dsz u32, samples}
//   kind "pal"  : 768-byte VGA palette
//   kind "font" : FONT {height i32, charofs[256] i16, width[256] i8} + char data
//   kind "map"  : MAZEDATA {size u32, spriteoff u32, numsprites u32, map[1350] u32, csprite[n] 24B}
//   kind "lib"  : 131 x 528B SPRITE records
//   kind "flat" : 672 x 8B FLATS records
//   kind "text" : raw text item
//   kind "raw"  : anything else (PC-speaker SFX variants etc.), included for completeness
//
// Naming: named items keep their GLB name; unnamed items following a named
// label "X" are named "X+1", "X+2", ... (FX data items, sprite frame runs).
// Items in the ranges of *_MUS labels (DMX music) are skipped.

const fs = require('fs');
const path = require('path');
const { GLB } = require('./glbparse.js');

const ROOT = path.join(__dirname, '..');
const OUT = path.join(ROOT, 'assets');

function isNamed(n) {
  return /^[A-Za-z0-9_]+$/.test(n) && !/^\d+$/.test(n);
}

function decodeGfx(buf) {
  if (buf.length < 20) return null;
  const v = new DataView(buf.buffer, buf.byteOffset, 20);
  const type = v.getUint32(0, true);
  const w = v.getInt32(12, true);
  const h = v.getInt32(16, true);
  if (type === 1) {
    if (buf.length !== 20 + w * h) return null;
    return { w, h };
  }
  if (type === 0) {
    let p = 20;
    while (true) {
      if (p + 16 > buf.length) return null;
      const len = v32(buf, p + 12);
      const off = v32(buf, p + 8);
      if (off === 0xffffffff) { p += 16; break; }
      p += 16 + len;
      if (p > buf.length) return null;
    }
    return { w, h };
  }
  return null;
}
function v32(buf, o) {
  return buf.readUInt32LE(o);
}

function build(file) {
  const glb = new GLB(fs.readFileSync(file));
  const entries = []; // {name, idx, buf, kind, w, h, rate, dsz}
  let lastLabel = null;
  let labelIdx = -1;
  let inMusic = false;

  for (let i = 0; i < glb.items.length; i++) {
    const it = glb.items[i];
    const named = isNamed(it.name);
    if (named) {
      lastLabel = it.name;
      labelIdx = i;
      inMusic = it.name.endsWith('_MUS');
      if (it.size === 0) continue; // pure label entry
    }
    if (inMusic) continue; // skip DMX music data
    if (it.size === 0) continue;
    let name;
    if (named) name = it.name;
    else if (lastLabel) name = lastLabel + '+' + (i - labelIdx);
    else name = 'UNK_' + i.toString(16);

    const buf = glb.fetch(it);
    const e = { name, idx: i, buf };
    const m = /^([A-Za-z0-9_]+_FX)\+(\d+)$/.exec(name);
    if (m) {
      // FX group data items; the 4th is the 11025Hz 8-bit digital sample
      if (buf.length >= 8) {
        const f0 = buf.readUInt16LE(0);
        const rate = buf.readUInt16LE(2);
        const dsz = buf.readUInt32LE(4);
        if (f0 === 3 && rate >= 8000 && rate <= 24000 && 8 + dsz === buf.length) {
          e.kind = 'sfx'; e.rate = rate; e.dsz = dsz;
        } else {
          e.kind = 'raw';
        }
      } else e.kind = 'raw';
    } else if (name === 'PALETTE_DAT' && buf.length === 768) {
      e.kind = 'pal';
    } else if (/_FNT$/.test(name)) {
      e.kind = 'font';
    } else if (/^MAP\dG\d_MAP$/.test(name)) {
      e.kind = 'map';
    } else if (/^SPRITE\d_ITM$/.test(name)) {
      e.kind = 'lib';
    } else if (/^FLATSG\d_ITM$/.test(name)) {
      e.kind = 'flat';
    } else if (/_TXT$/.test(name) || /_DIZ$/.test(name) || /_DIX$/.test(name)) {
      e.kind = 'text';
    } else {
      const g = decodeGfx(buf);
      if (g) { e.kind = 'gfx'; e.w = g.w; e.h = g.h; }
      else e.kind = 'raw';
    }
    entries.push(e);
  }
  return entries;
}

const f000 = build(path.join(ROOT, 'data/FILE0000.GLB'));
const f001 = build(path.join(ROOT, 'data/FILE0001.GLB'));
const entries = [...f000, ...f001];

// sanity checks for things the game code needs
const need = [
  'LPLAYER_PIC', 'LPLAYER_PIC+1', 'LPLAYER_PIC+2', 'LPLAYER_PIC+3', 'LPLAYER_PIC+4',
  'SHIP01G1_PIC', 'SHIP01G1_PIC+1',
  'N0_PIC', 'N9_PIC', 'NS_PIC',
  'SHLDLOW_PIC', 'WEPDEST_PIC', 'SMSHIELD_PIC', 'SMBOMB_PIC', 'ICNGLW_BLK',
  'NMSHOT_BLK', 'PLASMA_BLK', 'MICROM_BLK', 'MISDUM_BLK', 'MISRAT_BLK', 'MISGRD_BLK',
  'BLDGBOMB_PIC', 'POWDIS_BLK', 'MEGABM_BLK', 'SHOKWV_BLK', 'FRNTLAS_BLK', 'DETHRY_BLK',
  'ESHOT_BLK', 'EMISLE_BLK', 'MINE_BLK', 'ELASER_BLK', 'EPLASMA_PIC', 'COCONUT_PIC',
  'ELASEPOW_BLK', 'DETHPow_BLK'.toUpperCase(), 'LASERPOW_BLK', 'DRAYHIT_BLK',
  'GEXPLO_BLK', 'BOOM_PIC', 'SPLAT_BLK', 'BIGSPLAT_BLK', 'LGFLAK_BLK', 'EXPLO2_BLK',
  'SMFLAK_BLK', 'AIRBOOM_PIC', 'NRGBANG_BLK', 'LRBLST_BLK', 'SSMOKE_BLK', 'SMOKTRAL_BLK',
  'LGHTIN_BLK', 'BSPARK_BLK', 'OSPARK_BLK', 'GUNSTR_BLK', 'FLARE_PIC', 'SPARKLE_PIC',
  'SHIPGLOW_BLK',
  'BONUS00_PIC', 'BONUS14_PIC', 'BONUS15_PIC', 'BONUS21_PIC', 'BONUS22_PIC',
  'STARTG1TILES', 'SPRITE1_ITM', 'SPRITE2_ITM', 'SPRITE3_ITM', 'SPRITE4_ITM',
  'FLATSG1_ITM', 'FLATSG2_ITM', 'FLATSG3_ITM', 'FLATSG4_ITM',
  'MAP1G1_MAP', 'MAP9G1_MAP', 'PALETTE_DAT', 'SYSTEM_FNT', 'GAME_FNT', 'FONT1_FNT', 'FONT2_FNT',
  'GUN_FX+4', 'EXPLO_FX+4', 'EXPLO2_FX+4', 'GEXPLO_FX+4', 'ESHOT_FX+4', 'MISSLE_FX+4',
  'BONUS_FX+4', 'CRASH_FX+4', 'FLYBY_FX+4', 'WARN_FX+4', 'TURRET_FX+4', 'LASER_FX+4',
  'MON1_FX+4', 'MON6_FX+4', 'DAVE_FX+4', 'HIT_FX+4', 'EGRAb_FX+4'.toUpperCase(),
];
const have = new Set(entries.map(e => e.name));
const missing = need.filter(n => !have.has(n));
if (missing.length) {
  console.error('MISSING ENTRIES:', missing.join(', '));
  process.exit(1);
}

// palette
const palEntry = entries.find(e => e.kind === 'pal');
const palette = Array.from(palEntry.buf);

// write binary + index
const total = entries.reduce((a, e) => a + e.buf.length, 0);
const bin = Buffer.alloc(total);
let off = 0;
const indexEntries = [];
const names = {};
entries.forEach((e, i) => {
  e.buf.copy(bin, off);
  indexEntries.push({
    n: e.name, k: e.kind, o: off, s: e.buf.length,
    w: e.w, h: e.h, r: e.rate, d: e.dsz,
  });
  names[e.name] = i;
  off += e.buf.length;
});

fs.mkdirSync(OUT, { recursive: true });
fs.writeFileSync(path.join(OUT, 'raptor.bin'), bin);
fs.writeFileSync(path.join(OUT, 'index.json'),
  JSON.stringify({ v: 1, palette, items: indexEntries, names }));

const counts = {};
entries.forEach(e => { counts[e.kind] = (counts[e.kind] || 0) + 1; });
console.log(`entries: ${entries.length}  binary: ${(total / 1024 / 1024).toFixed(2)} MB`);
console.log('kinds:', JSON.stringify(counts));
console.log('sfx rate check:', ['GUN_FX+4', 'EXPLO_FX+4', 'GEXPLO_FX+4'].map(n =>
  `${n}=${entries.find(e => e.name === n).rate}`).join(' '));

