// Asset extractor: pulls real game data out of FILE0000.GLB / FILE0001.GLB and
// writes a single flat binary (assets/raptor.bin) plus a JSON index
// (assets/index.json) consumed by js/raptor.js.
//
// Layout of the binary: items concatenated in GLB order. Every entry is raw
// (decrypted) item bytes in its original format:
//   kind "gfx"  : GFX_PIC sprite/dense pic (see index for w/h)
//   kind "sfx"  : Apogee 8-bit PCM: {type u16, rate u16, dsz u32, samples}
//   kind "pal"  : 768-byte VGA palette
//   kind "font" : FONT {height i32, charofs[256] i16, width[256] i8} + char data
//   kind "map"  : MAZEDATA {size u32, spriteoff u32, numsprites u32, map[1350] u32, csprite[n] 24B}
//   kind "lib"  : 131 x 528B SPRITE records
//   kind "flat" : 672 x 8B FLATS records
//   kind "text" : raw text item
//   kind "raw"  : anything else
//
// Naming: named items keep their GLB name; repeated names get ".1", ".2", ...
// (e.g. the 7 LPLAYER_PIC ship frames). Unnamed items following a named label
// "X" are named "X+1", "X+2", ... (FX data items, tile runs).
// Skipped: DMX music ranges (*_MUS labels), AGX movie frames, menu/SWD chrome.

const fs = require('fs');
const path = require('path');
const { GLB } = require('./glbparse.js');

const ROOT = path.join(__dirname, '..');
const OUT = path.join(ROOT, 'assets');

function isNamed(n) {
  return /^[A-Za-z0-9_$]+$/.test(n) && !/^\d+$/.test(n);
}

const SKIP_NAMES = new Set([
  // big decorative screens & menu chrome (FILE0001)
  'BACKGRND_PIC', 'APOGEE_PIC', 'CYGNUS_PIC', 'TAIWARN_PIC', 'HANGER_PIC',
  'SHIPCOMP_PIC', 'STORE_PIC', 'SCREEN_PIC', 'REGISTER_PIC', 'RAPLOG_PIC',
  'RAPLOG2_PIC', 'SMRAPLOG_PIC', 'COPYRGHT_PIC', 'TEXTURE_PIC', 'STEXTURE_PIC',
  'STOREHLP_PIC', 'HELPCOMP_PIC', 'SMLAP_PIC', 'ADPIC1_PIC', 'ADPIC2_PIC',
  'ADPIC3_PIC', 'ADPIC4_PIC', 'CDIF1_PIC', 'CDIF2_PIC', 'CDIF3_PIC', 'CDIF4_PIC',
  'MENU1_PIC', 'MENU2_PIC', 'MENU3_PIC', 'MENU4_PIC', 'MENU5_PIC', 'MENU6_PIC',
  'MENU7_PIC', 'MENU8_PIC', 'WMALE_PIC', 'WFEMALE_PIC', 'BFEMALE_PIC',
  'BMALE_PIC', 'HAROLD_PIC', 'WMALEID_PIC', 'WFMALEID_PIC', 'BFMALEID_PIC',
  'BMALEID_PIC', 'BUTTON1_PIC', 'BUTTON2_PIC', 'BUTTON3_PIC', 'BUTTON4_PIC',
  'SLIDE_PIC', 'POINT_PIC', 'NUMBER_PIC', 'LIGHTON_PIC', 'LIGHTOFF_PIC',
  'QUESTION_PIC', 'CHKOFF_PIC', 'CHKON_PIC', 'BUYLGT_PIC', 'BUYDRK_PIC',
  'SELLGT_PIC', 'SELLDRK_PIC', 'BUYITEM_PIC', 'SELLITEM_PIC', 'PREV_PIC',
  'NEXT_PIC', 'CURSOR_PIC', 'POGPAL_DAT', 'CYGPAL_DAT', 'TAIPAL_DAT',
]);
function skipName(n) {
  if (!isNamed(n)) return false;
  if (n.endsWith('_AGX') || n.endsWith('_SWD') || n.endsWith('_PAL')) return true;
