  'SMFLAK_BLK', 'AIRBOOM_PIC', 'NRGBANG_BLK', 'LRBLST_BLK', 'SSMOKE_BLK',
  'SMOKTRAL_BLK', 'LGHTIN_BLK', 'BSPARK_BLK', 'OSPARK_BLK', 'GUNSTR_BLK',
  'FLARE_PIC', 'SPARKLE_PIC', 'SHIPGLOW_BLK',
  'BONUS00_PIC', 'BONUS14_PIC', 'BONUS15_PIC', 'BONUS21_PIC', 'BONUS22_PIC',
  'STARTG1TILES+1', 'STARTG1TILES+672', 'SPRITE1_ITM', 'FLATSG1_ITM',
  'MAP1G1_MAP', 'MAP9G1_MAP', 'PALETTE_DAT', 'SYSTEM_FNT', 'GAME_FNT',
  'FONT1_FNT', 'FONT2_FNT',
  'GUN_FX+4', 'EXPLO_FX+4', 'EXPLO2_FX+4', 'GEXPLO_FX+4', 'ESHOT_FX+4',
  'MISSLE_FX+4', 'BONUS_FX+4', 'CRASH_FX+4', 'FLYBY_FX+4', 'WARN_FX+4',
  'TURRET_FX+4', 'LASER_FX+4', 'MON1_FX+4', 'MON6_FX+4', 'DAVE_FX+4',
  'HIT_FX+4', 'EGRAb_FX+4', 'JETSND_FX+4', 'THEME_FX+4', 'DOOR_FX+4', 'SWEP_FX+4',
