  'SHIPCOMP_PIC', 'STORE_PIC', 'SCREEN_PIC', 'REGISTER_PIC', 'RAPLOG_PIC',
  'RAPLOG2_PIC', 'SMRAPLOG_PIC', 'COPYRGHT_PIC', 'TEXTURE_PIC', 'STEXTURE_PIC',
  'STOREHLP_PIC', 'HELPCOMP_PIC', 'SMLAP_PIC', 'ADPIC1_PIC', 'ADPIC2_PIC',
  'ADPIC3_PIC', 'ADPIC4_PIC', 'CDIF1_PIC', 'CDIF2_PIC', 'CDIF3_PIC', 'CDIF4_PIC',
  'MENU1_PIC', 'MENU2_PIC', 'MENU3_PIC', 'MENU4_PIC', 'MENU5_PIC', 'MENU6_PIC',
  'MENU7_PIC', 'MENU8_PIC', 'WMALE_PIC', 'WFEMALE_PIC', 'BFEMALE_PIC',
  'BMALE_PIC', 'HAROLD_PIC', 'WMALEID_PIC', 'WFMALEID_PIC', 'BFMALEID_PIC',
