  'SMOKTRAL_BLK', 'LGHTIN_BLK', 'BSPARK_BLK', 'OSPARK_BLK', 'GUNSTR_BLK',
  'FLARE_PIC', 'SPARKLE_PIC', 'SHIPGLOW_BLK',
  'BONUS00_PIC', 'BONUS14_PIC', 'BONUS15_PIC', 'BONUS21_PIC', 'BONUS22_PIC',
  'STARTG1TILES+1', 'STARTG1TILES+672', 'SPRITE1_ITM', 'FLATSG1_ITM',
  'MAP1G1_MAP', 'MAP9G1_MAP', 'PALETTE_DAT', 'SYSTEM_FNT', 'GAME_FNT',
